export function mountCommunity({name,notify}){
 const $=id=>document.getElementById(id);let state=null,busy=false,offset=0,opened=false;
 const format=n=>Number(n).toLocaleString('en-US');
 function paint(){const draft=$('communityName')?.value,typing=document.activeElement?.id==='communityName';const available=!!state;$('convoyStatus').textContent=available?(state.feed?'LIVE COMMUNITY SHIFT':'LIVE SIGNAL PAUSED'):'COMMUNITY SERVER OFFLINE';$('convoyDay').textContent=state?state.day+' · UTC':'Online service required';$('convoyTotal').textContent=state?format(state.delivered)+' / '+state.goal:'— / 100';$('convoyProgress').style.width=state?Math.min(100,state.delivered/state.goal*100)+'%':'0%';$('convoyPeople').textContent=state?state.participants+' engineers on today’s shift':'Practice and local saves remain available.';$('convoyOpen').textContent=state?.player?'Open your community shift ↗':'Join the daily convoy ↗';
 if(!opened)return;if(typing&&!busy)return;const content=$('communityContent');content.replaceChildren();function el(tag,text,cls){let e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}content.append(el('p','THE COMMUNITY CONVOY','eyebrow'),el('h2','One wheel. A shared destination.'),el('p','Help complete 100 deliveries together each UTC day. This separate live challenge starts with 50 energy. The real hamster’s new measured work replenishes it. Practice stars and local saves never count.'));
 if(!state){content.append(el('p','The community server is unavailable. This static copy still supports the full single-player game. Global scores will appear when its Node service is connected.','modal-note'));return}
 content.append(el('p',state.delivered+' / '+state.goal+' deliveries · '+state.participants+' engineers · resets at 00:00 UTC','convoy-summary'));
 if(!state.player){content.append(el('p','Joining stores your engineer name and score on this server and displays them publicly. A secure browser cookie keeps your community identity. Names are display names, not verified or reserved accounts. Clearing cookies loses access; no wallet or password is required.'));
 let input=el('input');input.id='communityName';input.maxLength=20;input.value=draft??name()??'';input.placeholder='Engineer name';input.setAttribute('aria-label','Public engineer name');let join=el('button',busy?'Joining…':'Join today’s shift','run-button');join.disabled=busy;join.onclick=()=>act('/join',{name:input.value.trim()});content.append(input,join)
 }else{const p=state.player;content.append(el('p',p.name+' #'+p.id.slice(0,4)+' · '+Math.floor(p.energy)+' / 100 energy · '+p.score+' points','convoy-summary'));if(p.trip){const route=state.routes.find(r=>r.id===p.trip.route),remaining=Math.max(0,Math.ceil((p.trip.due-Date.now()-offset)/1000));content.append(el('p',(route?.name||'Delivery')+' · '+(remaining?remaining+' sec remaining':'Arriving…'),'modal-note'))}else for(const route of state.routes){let button=el('button',route.name+' · '+route.seconds+' sec · '+route.energy+' energy · +'+route.score+' points','convoy-route');button.disabled=busy||!state.feed||p.energy<route.energy;button.onclick=()=>act('/dispatch',{route:route.id});content.append(button)}content.append(el('p','Daily scores are calculated on the server. Deliveries finish using server time, including while you are away. Wheel energy is measured, not finalized onchain. No prizes or token value.'))}
 content.append(el('h3','Global daily leaderboard'));if(!state.leaderboard.length)content.append(el('p','No deliveries yet. Be the first train home.','board-empty'));else{const table=el('table',undefined,'ranking-table');let head=el('tr');for(let label of ['Rank','Engineer','Score','Deliveries'])head.append(el('th',label));table.append(head);for(const row of state.leaderboard){const tr=el('tr');if(row.id===state.player?.id)tr.className='you';for(const value of [row.rank,row.name+' #'+row.id.slice(0,4),format(row.score),row.delivered])tr.append(el('td',value));table.append(tr)}let scroll=el('div',undefined,'board-scroll');scroll.append(table);content.append(scroll)}
 }
 async function request(path,body){let r=await fetch('/api/community'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(12000)});let d=await r.json();if(!r.ok)throw Error(d.error||'Community service unavailable.');state=d;offset=d.serverTime-Date.now();paint()}
 async function refresh(){try{await request('/state')}catch{state=null;paint()}}
 async function act(path,body){if(busy)return;busy=true;try{await request(path,body);if(path==='/dispatch')notify('Community train dispatched!');else notify('You joined the community shift.')}catch(e){notify(e.message)}finally{busy=false;paint()}}
 $('convoyOpen').onclick=()=>{opened=true;$('communityModal').showModal();paint();refresh()};$('communityClose').onclick=()=>$('communityModal').close();$('communityModal').addEventListener('close',()=>opened=false);
 refresh();const poll=setInterval(()=>{if(!document.hidden&&!busy)refresh()},10000);const clock=setInterval(()=>{if(opened&&state?.player?.trip)paint()},1000);return {open(){$('convoyOpen').click()}};
}
